<?php
if (!defined('ABSPATH')) exit;
final class DSVS_Renderer {
    public static function error($detail=''){return '<p class="dsvs-error">Die DSVS-Daten konnten momentan nicht geladen werden.'.($detail?' <small>'.esc_html($detail).'</small>':'').'</p>';}
    public static function notice($text){return '<p class="dsvs-notice">'.esc_html($text).'</p>';}
    private static function heading($league,$subtitle,$show){if(!$show)return '';return '<header class="dsvs-heading"><h2>'.esc_html($league['name']).'</h2><h3>'.esc_html($subtitle).'</h3></header>';}
    public static function standings($rows,$league,$show_title=true){ob_start();?><section class="dsvs-block"><?php echo self::heading($league,'Tabelle',$show_title); ?><div class="dsvs-table-wrap"><table class="dsvs-table dsvs-standings"><thead><tr><?php foreach(array('Platz','Mannschaft','S','G','U','V','Pkt.','Diff.','Partien') as $h):?><th><?php echo esc_html($h);?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr<?php echo DSVS_Parser::is_owned($r[1])?' class="dsvs-own-team"':'';?>><?php foreach($r as $i=>$v):?><td<?php echo $i===1?' class="dsvs-team"':'';?>><?php echo esc_html($v);?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><?php return ob_get_clean();}
    public static function games($games,$league,$subtitle,$id='',$show_title=true,$poll=false){ob_start();?><section<?php echo $id?' id="'.esc_attr($id).'"':'';?> class="dsvs-block dsvs-games"<?php echo $poll?' data-dsvs-league="'.esc_attr($league['key']).'"':'';?>><?php echo self::heading($league,$subtitle,$show_title);?><?php self::game_table($games,false);?><small class="dsvs-updated">Zuletzt geprüft: <?php echo esc_html(current_time('H:i:s'));?> Uhr</small></section><?php return ob_get_clean();}
    public static function combined_games($games,$title,$show_title=true,$errors=array()){ob_start();?><section class="dsvs-block dsvs-games"><?php if($show_title):?><header class="dsvs-heading"><h2><?php echo esc_html($title);?></h2></header><?php endif;?><?php self::game_table($games,true);?><?php if($errors):?><small class="dsvs-warning">Teilweise nicht geladen: <?php echo esc_html(implode(', ',$errors));?></small><?php endif;?></section><?php return ob_get_clean();}
    private static function game_table($games,$league_column){if(!$games){echo '<p>Keine passenden Spiele gefunden.</p>';return;}?><div class="dsvs-table-wrap"><table class="dsvs-table"><thead><tr><?php if($league_column):?><th>Liga</th><?php endif;?><th>ST</th><th>Termin</th><th>Heim</th><th>Ergebnis</th><th>Gast</th></tr></thead><tbody><?php foreach($games as $g):?><tr<?php echo DSVS_Parser::is_owned($g['home'])||DSVS_Parser::is_owned($g['away'])?' class="dsvs-own-team"':'';?>><?php if($league_column):?><td><?php echo esc_html($g['league']['key']);?></td><?php endif;?><td><?php echo esc_html($g['matchday']);?></td><td><?php echo esc_html($g['date'].' '.$g['time']);?></td><td class="dsvs-team"><?php echo esc_html($g['home']);?></td><td class="dsvs-result"><?php echo esc_html($g['result']);?></td><td class="dsvs-team"><?php echo esc_html($g['away']);?></td></tr><?php endforeach;?></tbody></table></div><?php }
}
